#!/usr/bin/env node
// Sections 063 to 067. An improvement to how generations are judged, and a
// backtest of it against the generations already run.
//
// GA1, GA2 and GA3 each promoted a winner under a threshold fixed in advance,
// and the apparatus around them got steadily stricter: GA3 put the null
// candidate in its own tournament and separated cleanly, which is what GA1 and
// GA2 failed to do. It still promoted a solver that answers a question nobody
// asked.
//
// The defect was never in a tournament. It was in the evaluation every
// tournament drew from: items generated by the same process the candidates were
// built against, so a lookup over that process scores exactly like a mechanism.
// No amount of care inside the tournament reaches that, which is why this is a
// meta-improvement rather than another generation.
//
// A criterion change that cannot be backtested is an opinion. So this applies
// the new gate to the candidates already scored and reports whether it would
// have changed the outcome -- including the case where it changes nothing.
import { writeFileSync, mkdirSync, readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { dirname, resolve, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { GA3_CANDIDATES } from '../src/nullstar-ga3-candidates.mjs';
import { GATING_PROBES, REPORTING_PROBES, runProbes, gateVerdict } from '../src/nullstar-out-of-pattern-probes.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = process.env.NULLSTAR_META_OUT || 'artifacts/nullstar-terminal/meta-improvement-v2.json';
const head = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim();
const ga3 = JSON.parse(readFileSync(join(root, 'artifacts/nullstar-terminal/ga3-result.json'), 'utf8'));

// The backtest. GA3 is the only generation whose candidates can be replayed:
// GA1's and GA2's families have no out-of-pattern probe set, and inventing one
// now to judge a finished run would be choosing the test after knowing the
// answer.
const replay = Object.entries(GA3_CANDIDATES).map(([name, fn]) => {
  const recorded = ga3.candidates.find(row => row.candidate === name);
  const result = runProbes(fn, GATING_PROBES.INVENTION);
  const gate = gateVerdict(result, { minimumCorrectRate: 0 });
  return {
    candidate: name,
    recordedHeldOutScore: recorded?.heldOutScore ?? null,
    wasEligibleUnderOldCriterion: recorded?.eligible ?? false,
    outOfPattern: { correct: result.correct, refused: result.refused, confabulated: result.confabulated, of: result.of },
    passesNewGate: gate.passes,
    gateReason: gate.reason,
    eligibleUnderNewCriterion: Boolean(recorded?.eligible) && gate.passes
  };
});

const oldWinner = ga3.winner;
const stillEligible = replay.filter(row => row.eligibleUnderNewCriterion);
const newWinner = stillEligible.length
  ? stillEligible.sort((a, b) => (b.recordedHeldOutScore - a.recordedHeldOutScore))[0].candidate
  : null;

// What the runner-up would have done, for the counterfactual. It is not
// promoted here -- it did not clear a threshold fixed before the run, and
// moving that bar now is the failure this apparatus exists to prevent.
const runnerUp = runProbes(GA3_CANDIDATES.I4_COMPOSITIONAL_SEARCH, GATING_PROBES.INVENTION);
const runnerUpHeldBack = runProbes(GA3_CANDIDATES.I4_COMPOSITIONAL_SEARCH, REPORTING_PROBES.INVENTION);

const artifact = {
  schemaVersion: 'uberbond-nullstar-meta-improvement-2.0.0',
  directiveSections: ['063', '064', '065', '066', '067'],
  supersedes: 'artifacts/nullstar-omega/meta-improvement.json',
  whySuperseded: 'That artifact reasoned about a generation loop running on the corpus later retired for being tautological. The loop it describes was real; the evidence it scored was not.',
  generatedAt: new Date().toISOString(),
  sourceCommit: head,

  symptom: 'GA3 promoted a solver scoring 1.0 on every item its generator emits which answers none built from the same primitives in a new arrangement, and on one of those returns the answer to a different question rather than refusing.',
  whereTheDefectWas: 'Not in the tournament. GA3 ran the strictest tournament of the three -- null candidate included, clean separation, threshold fixed beforehand -- and promoted the wrong mechanism anyway. The evaluation drew every item from the process the candidates were built against, so a lookup over that process is indistinguishable from a mechanism no matter how the tournament is run.',
  whyThisIsMetaAndNotAnotherGeneration: 'A generation changes a solver. This changes what any future generation must survive, so it applies to solvers not yet written.',

  change: {
    what: 'A declaration may set outOfPatternGate. Candidates are then run against items built outside the generator, reusing its primitives and phrasing with only the combination changed. Confabulating on any of them disqualifies at any in-distribution score.',
    whyConfabulationIsAbsolute: 'A solver that returns nothing outside its competence is usable, because a caller can tell. One that returns a confident wrong number is not, because nothing downstream can separate its right answers from its wrong ones. That is a different kind of defect from being narrow, and a rate would let a high score buy it off.',
    probesAreSplit: 'One set gates, a disjoint set is held back for reporting. A candidate tuned against the probe that judges it would otherwise be congratulated by the same items.',
    probesNeverScored: 'Gating probes do not enter the headline mean. They can only remove a candidate, never raise one.'
  },

  backtest: {
    question: 'Applied to GA3, does the new gate change the outcome?',
    onlyGa3ReplayableBecause: 'GA1 and GA2 attacked families with no probe set. Inventing one now to re-judge a finished run would be choosing the test after knowing the answer.',
    replay,
    winnerUnderOldCriterion: oldWinner,
    winnerUnderNewCriterion: newWinner,
    changesOutcome: newWinner !== oldWinner,
    finding: newWinner === null
      ? 'Under the new gate GA3 promotes nothing. Every candidate that cleared the in-distribution threshold either confabulates out of pattern or fails it, which is the honest reading: the generation found no mechanism, only a better lookup.'
      : newWinner !== oldWinner
        ? `Under the new gate GA3 would have promoted ${newWinner} instead of ${oldWinner}.`
        : 'The new gate does not change GA3. It would have promoted the same candidate.'
  },

  counterfactualRunnerUp: {
    candidate: 'I4_COMPOSITIONAL_SEARCH',
    recordedHeldOutScore: ga3.candidates.find(row => row.candidate === 'I4_COMPOSITIONAL_SEARCH')?.heldOutScore ?? null,
    onGatingProbes: { correct: runnerUp.correct, refused: runnerUp.refused, confabulated: runnerUp.confabulated, of: runnerUp.of },
    onHeldBackProbes: { correct: runnerUpHeldBack.correct, refused: runnerUpHeldBack.refused, confabulated: runnerUpHeldBack.confabulated, of: runnerUpHeldBack.of },
    notPromotedHere: true,
    whyNot: 'It scored 0.8 against a threshold of "above 0.8" fixed before the run. Promoting it now because a later probe favours it would be moving a bar after seeing which side of it the better answer landed on. It competes again in GA4, under criteria declared in advance, like any other candidate.'
  },

  whatThisCannotEstablish: 'A gate that would have caught one known failure is not a gate that catches unknown ones. The probes are hand-built by the same author as the solvers and share his blind spots; they are a floor under future promotions, not proof that a promotion which clears them has learned a mechanism.',
  truthBoundary: 'THIS CHANGES A SELECTION CRITERION AND BACKTESTS IT AGAINST ONE GENERATION. IT IS NOT EVIDENCE OF IMPROVED INTELLIGENCE, ACCELERATION, OR RECURSIVE SELF-IMPROVEMENT.',
  businessEffectAuthority: 'NONE',
  externalEffects: { providerCalls: 0, spendCents: 0, networkCalls: 0, messagesSent: 0 }
};

const outPath = resolve(root, OUT);
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, `${JSON.stringify(artifact, null, 2)}\n`);

console.log(`meta-improvement v2 @ ${head.slice(0, 8)}`);
console.log('\n  backtest of the new gate against GA3:');
for (const row of replay) {
  console.log(`    ${row.candidate.padEnd(24)} held-out ${row.recordedHeldOutScore}  out-of-pattern ${row.outOfPattern.correct}/${row.outOfPattern.of} correct ${row.outOfPattern.confabulated} confabulated  ${row.passesNewGate ? 'gate passes' : 'GATE FAILS'}`);
}
console.log(`\n  old winner: ${oldWinner}`);
console.log(`  new winner: ${newWinner ?? 'NONE'}`);
console.log(`  ${artifact.backtest.finding}`);
